SELECT  FROM t_orders
WHERE 
  buyer_id=#{user}
  vendor_id=#{user}
  (buyer_id=#{user} OR vendor_id=#{user})

ORDER BY created_at DESC,id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id,title,item_desc,expect_price,status,city,visibility,trip_type,created_at
FROM t_demands WHERE publisher_id=#{user}
ORDER BY created_at DESC,id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id,destination,destination_flag,status,verify_status,depart_date,return_date,trip_type,created_at
FROM t_trips WHERE owner_id=#{user}
ORDER BY created_at DESC,id DESC LIMIT #{limit} OFFSET #{offset}
